[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path $ProjectRoot).Path;if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'};$rel=$PacketPath.Replace('\','/').Trim();if($rel.Contains('..')-or $rel -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'};$full=Join-Path $root ($rel.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path $full -PathType Leaf)){throw "Session packet missing: $rel"};$p=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes((Resolve-Path $full)))|ConvertFrom-Json;foreach($x in @('stateSchemaVersion','recordId','sessionId','responsibilityKey','taskFingerprint','contextAccepted','envelopeHash','snapshotHash','authority','lifecycle')){if($null -eq $p.PSObject.Properties[$x]){throw "Session field missing: $x"}};if([string]$p.stateSchemaVersion -ne '2'){throw 'Only session state schema v2 is accepted.'};if([string]$p.authority -ne 'sessions.json'){throw 'sessions.json must remain the unique session authority.'};if([bool]$p.contextAccepted -and ([string]$p.envelopeHash -notmatch '^[0-9a-fA-F]{64}$'-or [string]$p.snapshotHash -notmatch '^[0-9a-fA-F]{64}$')){throw 'Accepted context requires envelope and immutable snapshot hashes.'};if([string]$p.lifecycle -eq 'title-only'){throw 'Title-only identity is not routable authority.'};Write-Output "PASS: session packet uses schema v2, unique authority, immutable identity and acceptance evidence: $rel"
